begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','35000000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('35000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','decision-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,6) i;
select pg_temp.login(1);
create temp table ctx as select public.create_project('Decision fixture','Europe/London','GBP','2026-01-01') id;
create temp table cat as with c as(insert into public.project_areas(project_id,title) select id,'Stay' from ctx returning id) select * from c;
set local role postgres;
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.id,('35000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Decision member',case when i=4 then 'viewer' else 'member' end::public.member_role,'active' from ctx,generate_series(2,4) i;
select pg_temp.login(6);
create temp table other as select public.create_project('Other decision project','UTC','GBP','2026-01-01') id;
create temp table other_cat as with c as(insert into public.project_areas(project_id,title) select id,'Other' from other returning id) select * from c;
create temp table other_dec as select public.create_decision((select id from other),'Other?',null,null,'[{"title":"X"},{"title":"Y"}]') id;
create temp table other_opt as select id from public.decision_options where decision_id=(select id from other_dec) limit 1;
select pg_temp.login(2);
create temp table dec as select public.create_decision((select id from ctx),'Where to stay?',null,now()+interval '2 days','[{"title":"Villa A","estimated_cost_minor":285000},{"title":"Villa B","estimated_cost_minor":310000},{"title":"Hotel C"}]') id;
create temp table opts as select id,title from public.decision_options where decision_id=(select id from dec);
create temp table token as select public.create_resource_share_link('decision',(select id from dec)) a;
select is(public.create_decision((select id from ctx),'Where to stay?',null,null,'[{"title":"A"},{"title":"B"}]',(select id from dec)),(select id from dec),'Stable creation request idempotent');
select is(jsonb_array_length(public.get_decisions((select id from ctx))),1,'One Decision');
select throws_ok($$select public.create_decision((select id from ctx),'Bad',null,null,'[{"title":"A"}]')$$,'22023',null,'Minimum two options');
select throws_ok($$select public.create_decision((select id from ctx),'Bad',null,null,'[{"title":" A "},{"title":"a"}]')$$,'22023',null,'Distinct normalized options');
select throws_ok($$select public.create_decision((select id from ctx),'Bad',null,now()-interval '1 day','[{"title":"A"},{"title":"B"}]')$$,'22023',null,'Past deadline denied');
select throws_ok($$select public.create_decision((select id from ctx),'Bad',null,null,'[{"title":"A","estimated_cost_minor":-1},{"title":"B"}]')$$,'22023',null,'Negative estimate denied');
select throws_ok($$select public.convert_decision_to_activity((select id from dec),(select id from cat))$$,'P0001',null,'Unresolved cannot convert');
select lives_ok($$select public.edit_decision((select id from dec),'Where to stay?','Advisory choice',now()+interval '2 days',null)$$,'Creator edits');
select pg_temp.login(3);
select is(public.resolve_shared_resource((select a from token))->>'resource_type','decision','Member can resolve route');
select throws_ok($$select public.get_resource_share_link('decision',(select id from dec))$$,'42501',null,'Ordinary member cannot manage sharing');
select throws_ok($$select public.resolve_decision((select id from dec),(select id from opts where title='Villa A'))$$,'42501',null,'Ordinary member cannot resolve');
select throws_ok($$select public.edit_decision((select id from dec),'Changed',null,null,null)$$,'42501',null,'Ordinary member cannot edit');
select lives_ok($$select public.cast_decision_vote((select id from dec),(select id from opts where title='Villa A'))$$,'Member casts vote');
select lives_ok($$select public.cast_decision_vote((select id from dec),(select id from opts where title='Villa A'))$$,'Exact vote retry');
select lives_ok($$select public.cast_decision_vote((select id from dec),(select id from opts where title='Villa B'))$$,'Vote change');
select is((select count(*)::int from public.decision_votes where decision_id=(select id from dec)),1,'One effective own vote');
select throws_ok($$select public.cast_decision_vote((select id from dec),(select id from other_opt))$$,'22023',null,'Cross-project option denied');
select throws_ok($$update public.decisions set status='resolved' where id=(select id from dec)$$,'42501',null,'Direct status mutation denied');
select throws_ok($$delete from public.decision_votes where decision_id=(select id from dec)$$,'42501',null,'Direct vote mutation denied');
select throws_ok($$select app.evaluate_decision_deadlines()$$,'42501',null,'Client cannot run evaluator');
select throws_ok($$select app.emit_domain_event('decision.created',(select id from ctx),(select id from dec),'{}','fake')$$,'42501',null,'Client cannot emit facts');
select pg_temp.login(4);
select lives_ok($$select public.cast_decision_vote((select id from dec),(select id from opts where title='Villa A'))$$,'Viewer may participate');
select is((select count(*)::int from public.decision_votes where decision_id=(select id from dec)),1,'Viewer cannot list other ballots');
select is(public.get_decisions((select id from ctx))->0->>'vote_count','2','Read model aggregates hidden ballots');
select throws_ok($$select public.create_decision((select id from ctx),'Viewer?',null,null,'[{"title":"A"},{"title":"B"}]')$$,'42501',null,'Viewer cannot create');
select throws_ok($$select public.create_resource_share_link('decision',(select id from dec))$$,'42501',null,'Viewer cannot manage share');
select is(public.resolve_shared_resource((select a from token))->>'resource_id',(select id::text from dec),'Viewer reads share through membership');
select pg_temp.login(2);
select throws_ok($$select public.edit_decision((select id from dec),'Where to stay?',null,null,'[{"title":"A"},{"title":"B"}]')$$,'P0001',null,'Options fixed after participation');
select pg_temp.login(5);
select is((select count(*)::int from public.decisions where project_id=(select id from ctx)),0,'Nonmember RLS');
select is((select count(*)::int from public.decision_options where project_id=(select id from ctx)),0,'Nonmember option RLS');
select is(public.resolve_shared_resource((select a from token)),'{"state":"unavailable"}'::jsonb,'Share grants no access');
select throws_ok($$select public.get_decisions((select id from ctx))$$,'42501',null,'Read RPC denies nonmember');
select throws_ok($$select public.cast_decision_vote((select id from dec),(select id from opts where title='Villa A'))$$,'42501',null,'Nonmember cannot vote');
select pg_temp.login(1);
create temp table jt as select public.regenerate_project_join_link((select id from ctx)) t;
select pg_temp.login(5);
select public.request_project_access((select t from jt));
select is(public.resolve_shared_resource((select a from token)),'{"state":"unavailable"}'::jsonb,'Pending requester share denied');
select throws_ok($$select public.cast_decision_vote((select id from dec),(select id from opts where title='Villa A'))$$,'42501',null,'Pending requester vote denied');
set local role postgres;
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in ('public.decisions'::regclass,'public.decision_options'::regclass,'public.decision_votes'::regclass)),'All Decision tables FORCE RLS');
select is((select count(*)::int from app.domain_events where resource_id=(select id from dec) and event_type='decision.created'),1,'Creation fact once');
select is((select count(*)::int from app.domain_events where resource_id=(select id from dec) and event_type='decision.vote_cast'),3,'Genuine vote changes only');
select is((select count(*)::int from public.notifications where decision_id=(select id from dec)),0,'No creation or vote spam');
select ok((select bool_and(payload='{}'::jsonb) from app.domain_events where resource_id=(select id from dec)),'No vote preference in event payload');
select ok(not exists(select 1 from public.audit_log where entity_type='decision_votes' and (before ? 'option_id' or after ? 'option_id')),'Audit excludes ballot preference');
update public.decisions set voting_deadline=now()-interval '1 minute' where id=(select id from dec);
select set_config('request.jwt.claims','{}',true);
select lives_ok($$select app.evaluate_decision_deadlines()$$,'Trusted deadline evaluator');
select lives_ok($$select app.evaluate_decision_deadlines()$$,'Evaluator retry');
select is((select count(*)::int from app.domain_events where resource_id=(select id from dec) and event_type='decision.deadline_reached'),1,'Deadline fact once per version');
select is((select count(*)::int from public.notifications where decision_id=(select id from dec)),2,'Creator and Organizer only deadline notifications');
select pg_temp.login(3);
select throws_ok($$select public.cast_decision_vote((select id from dec),(select id from opts where title='Villa A'))$$,'P0001',null,'Past deadline blocks votes');
select is((select count(*)::int from public.v_my_decision_notifications where decision_id=(select id from dec)),0,'Member cannot see manager inbox');
select pg_temp.login(1);
select ok(exists(select 1 from public.get_project_timeline_events((select id from ctx),now()-interval '1 day',now()+interval '1 day') where subject_id=(select id from dec) and status='voting_closed'),'Deadline timeline projection');
select ok(exists(select 1 from app._health_findings((select id from ctx)) where subject_id=(select id from dec) and code='decision_needs_resolution'),'Overdue unresolved attention');
select lives_ok($$select public.resolve_decision((select id from dec),(select id from opts where title='Villa B'))$$,'Organizer manually resolves tied vote');
select lives_ok($$select public.resolve_decision((select id from dec),(select id from opts where title='Villa B'))$$,'Exact resolution retry');
select throws_ok($$select public.resolve_decision((select id from dec),(select id from opts where title='Villa A'))$$,'P0001',null,'Conflicting resolution rejected');
select throws_ok($$select public.cast_decision_vote((select id from dec),(select id from opts where title='Villa A'))$$,'P0001',null,'Resolved voting blocked');
select throws_ok($$select public.convert_decision_to_activity((select id from dec),null)$$,'22023',null,'Category required');
select throws_ok($$select public.convert_decision_to_activity((select id from dec),(select id from other_cat))$$,'22023',null,'Foreign Category rejected');
select is((select total_cost_minor from public.v_project_financials where project_id=(select id from ctx)),0::bigint,'Decision option costs excluded from financial totals');
select is((select count(*)::int from public.commitments where project_id=(select id from ctx)),0,'Decision costs have not created commitments');
create temp table converted as select public.convert_decision_to_activity((select id from dec),(select id from cat)) id;
select is(public.convert_decision_to_activity((select id from dec),(select id from cat)),(select id from converted),'Conversion retry returns same Activity');
select is((select title from public.commitments where id=(select id from converted)),'Villa B','Server-selected title copied');
select is((select estimated_cost_minor from public.commitments where id=(select id from converted)),310000::bigint,'Minor-unit estimate copied');
select is((select total_cost_minor from public.v_project_financials where project_id=(select id from ctx)),310000::bigint,'Only converted Activity counted financially');
select is((select net_actual_spend_minor from public.v_project_financials where project_id=(select id from ctx)),0::bigint,'Conversion creates no payment');
select is((select count(*)::int from public.commitments where project_id=(select id from ctx)),1,'Single normal Activity');
select ok(not exists(select 1 from app._health_findings((select id from ctx)) where subject_id=(select id from dec)),'Resolved no longer needs attention');
set local role postgres;
select is((select count(*)::int from public.notifications where decision_id=(select id from dec) and kind='decision_resolved'),3,'Resolved notifications to active peers including Viewer');
select is((select count(*)::int from app.domain_events where resource_id=(select id from dec) and event_type='decision.resolved'),1,'One resolution fact');
select ok(not exists(select 1 from app.domain_events e where e.resource_id=(select id from dec) and not exists(select 1 from app.domain_event_processing p where p.event_id=e.id)),'All facts processed');
select pg_temp.login(2);
select lives_ok($$select public.soft_delete_decision((select id from dec))$$,'Creator soft-deletes');
select is((select count(*)::int from public.decisions where id=(select id from dec)),0,'Deleted Decision hidden');
select is(public.resolve_shared_resource((select a from token)),'{"state":"unavailable"}'::jsonb,'Deleted Decision share unavailable');
select is((select count(*)::int from public.commitments where id=(select id from converted)),1,'Converted Activity independent');
select pg_temp.login(1);
create temp table lifecycle as select public.create_decision((select id from ctx),'Lifecycle',null,null,'[{"title":"First"},{"title":"Second"}]') id;
select lives_ok($$select public.edit_decision((select id from lifecycle),'Lifecycle',null,now()+interval '1 day','[{"title":"One"},{"title":"Two"},{"title":"Three"}]')$$,'Options replaceable before voting');
create temp table lifecycle_opts as select id,title from public.decision_options where decision_id=(select id from lifecycle);
select pg_temp.login(3);
select public.cast_decision_vote((select id from lifecycle),(select id from lifecycle_opts where title='One'));
select lives_ok($$select public.cast_decision_vote((select id from lifecycle),null)$$,'Own vote removal');
select is(public.get_decisions((select id from ctx),(select id from lifecycle))->0->>'vote_count','0','Removal updates aggregate');
select public.cast_decision_vote((select id from lifecycle),(select id from lifecycle_opts where title='Two'));
set local role postgres;
update public.project_members set status='removed' where project_id=(select id from ctx) and user_id='35000000-0000-4000-8000-000000000003';
select pg_temp.login(3);
select throws_ok($$select public.cast_decision_vote((select id from lifecycle),null)$$,'42501',null,'Removed voter loses access');
select is((select count(*)::int from public.decisions where project_id=(select id from ctx)),0,'Removed voter cannot read');
select pg_temp.login(1);
select is(public.get_decisions((select id from ctx),(select id from lifecycle))->0->>'vote_count','1','Removed voter history still counted');
select throws_ok($$select public.edit_decision((select id from lifecycle),'Lifecycle',null,null,'[{"title":"One"},{"title":"Two"}]')$$,'P0001',null,'Options remain frozen after participation');
create temp table life_token as select public.create_resource_share_link('decision',(select id from lifecycle)) a;
create temp table life_new as select public.regenerate_resource_share_link('decision',(select id from lifecycle)) b;
select is(public.resolve_shared_resource((select a from life_token)),'{"state":"unavailable"}'::jsonb,'Decision rotation invalidates old token');
select is(public.resolve_shared_resource((select b from life_new))->>'resource_id',(select id::text from lifecycle),'New Decision token works');
select public.disable_resource_share_link('decision',(select id from lifecycle));
select is(public.resolve_shared_resource((select b from life_new)),'{"state":"unavailable"}'::jsonb,'Decision disable invalidates token');
set local role postgres;
update public.projects set status='archived' where id=(select id from ctx);
update public.decisions set voting_deadline=now()-interval '1 minute' where id=(select id from lifecycle);
select set_config('request.jwt.claims','{}',true);
select app.evaluate_decision_deadlines();
select is((select count(*)::int from app.domain_events where resource_id=(select id from lifecycle) and event_type='decision.deadline_reached'),0,'Archived ignored by evaluator');
select pg_temp.login(1);
select is(jsonb_array_length(public.get_decisions((select id from ctx),(select id from lifecycle))),1,'Archived reads retained');
select throws_ok($$select public.cast_decision_vote((select id from lifecycle),(select id from lifecycle_opts where title='One'))$$,'42501',null,'Archived vote denied');
select throws_ok($$select public.resolve_decision((select id from lifecycle),(select id from lifecycle_opts where title='One'))$$,'42501',null,'Archived resolution denied');
select throws_ok($$select public.edit_decision((select id from lifecycle),'No',null,null,null)$$,'42501',null,'Archived edit denied');
select throws_ok($$select public.create_resource_share_link('decision',(select id from lifecycle))$$,'42501',null,'Archived share mutation denied');
select throws_ok($$select public.convert_decision_to_activity((select id from lifecycle),(select id from cat))$$,'42501',null,'Archived conversion denied');
set local role postgres;
update public.projects set status='active' where id=(select id from ctx);
select pg_temp.login(1);
select public.edit_decision((select id from lifecycle),'Lifecycle',null,now()+interval '1 day',null);
set local role postgres;
select set_config('request.jwt.claims','{}',true);
select app.evaluate_decision_deadlines();
select is((select count(*)::int from app.domain_events where resource_id=(select id from lifecycle) and event_type='decision.deadline_reached'),0,'Changed future deadline does not emit old version');
update public.decisions set voting_deadline=now()-interval '1 minute' where id=(select id from lifecycle);
select app.evaluate_decision_deadlines();
select app.evaluate_decision_deadlines();
select is((select count(*)::int from app.domain_events where resource_id=(select id from lifecycle) and event_type='decision.deadline_reached'),1,'Current deadline version fires once');
select pg_temp.login(1);
select public.edit_decision((select id from lifecycle),'Lifecycle',null,now()+interval '2 days',null);
set local role postgres;
update public.decisions set voting_deadline=now()-interval '1 minute' where id=(select id from lifecycle);
select set_config('request.jwt.claims','{}',true);
select app.evaluate_decision_deadlines();
select is((select count(*)::int from app.domain_events where resource_id=(select id from lifecycle) and event_type='decision.deadline_reached'),2,'New deadline version can emit new historical fact');
select ok((select bool_and(actor_user_id is null) from app.domain_events where event_type='decision.deadline_reached' and project_id=(select id from ctx)),'Scheduled facts have system actor');
select pg_temp.login(1);
create temp table read_notification as select id from public.v_my_decision_notifications where decision_id=(select id from lifecycle) limit 1;
select is(public.mark_notification_read((select id from read_notification)),(select id from read_notification),'Decision inbox mark read returns ID');
select ok((select read_at is not null from public.v_my_decision_notifications where id=(select id from read_notification)),'Decision read state persisted');
create temp table zero_dec as select public.create_decision((select id from ctx),'Zero votes',null,null,'[{"title":"Yes"},{"title":"No"}]') id;
select lives_ok($$select public.resolve_decision((select id from zero_dec),(select id from public.decision_options where decision_id=(select id from zero_dec) limit 1))$$,'Zero-vote manual resolution');
select pg_temp.login(2);
create temp table creator_dec as select public.create_decision((select id from ctx),'Creator removal',null,now()+interval '1 day','[{"title":"Alpha"},{"title":"Beta"}]') id;
create temp table creator_option as select id from public.decision_options where decision_id=(select id from creator_dec) limit 1;
select throws_ok($$select public.cast_decision_vote((select id from creator_dec),(select id from lifecycle_opts where title='One'))$$,'22023',null,'Same-project other Decision option rejected');
set local role postgres;
update public.project_members set status='removed' where project_id=(select id from ctx) and user_id='35000000-0000-4000-8000-000000000002';
select pg_temp.login(2);
select throws_ok($$select public.resolve_decision((select id from creator_dec),(select id from creator_option))$$,'42501',null,'Removed creator cannot resolve');
select pg_temp.login(1);
select lives_ok($$select public.resolve_decision((select id from creator_dec),(select id from creator_option))$$,'Organizer retains authority after creator removal');
select is((select occurs_at from public.get_project_timeline_events((select id from ctx),now(),now()+interval '2 days') where subject_id=(select id from creator_dec)),(select voting_deadline from public.decisions where id=(select id from creator_dec)),'Timeline preserves exact canonical timestamp');
create temp table removed_deadline as select public.create_decision((select id from ctx),'Deadline removed',null,now()+interval '1 day','[{"title":"Alpha"},{"title":"Beta"}]') id;
select public.edit_decision((select id from removed_deadline),'Deadline removed',null,null,null);
set local role postgres;
update public.decisions set voting_deadline=now()-interval '1 minute' where id=(select id from creator_dec);
select set_config('request.jwt.claims','{}',true);
select app.evaluate_decision_deadlines();
select is((select count(*)::int from app.domain_events where resource_id in (select id from removed_deadline union all select id from creator_dec) and event_type='decision.deadline_reached'),0,'Removed deadlines and resolved Decisions never emit deadline facts');
select pg_temp.login(1);
create temp table anon_token as select public.create_resource_share_link('decision',(select id from removed_deadline)) a;
grant select on ctx,dec,anon_token to anon;
set local role anon;
select set_config('request.jwt.claims','{}',true);
select is(public.resolve_shared_resource((select a from anon_token)),'{"state":"sign_in"}'::jsonb,'Anonymous Decision link reveals only sign-in state');
select throws_ok($$select * from public.decisions$$,'42501',null,'Anonymous normal reads denied');
select throws_ok($$select public.get_decisions((select id from ctx))$$,'42501',null,'Anonymous read model denied');
select throws_ok($$select public.create_decision((select id from ctx),'No',null,null,'[{"title":"A"},{"title":"B"}]')$$,'42501',null,'Anonymous mutation denied');
select pg_temp.login(1);

select public.soft_delete_project((select id from ctx));
select is((select count(*)::int from public.decisions where project_id=(select id from ctx)),0,'Project cleanup hides Decisions');
select is((select count(*)::int from public.decision_options where project_id=(select id from ctx)),0,'Project cleanup hides options');
select is((select count(*)::int from public.v_my_decision_notifications where project_id=(select id from ctx)),0,'Project cleanup hides inbox');
set local role postgres;
select set_config('request.jwt.claims','{}',true);
create temp table event_total as select count(*) n from app.domain_events where project_id=(select id from ctx);
select app.evaluate_decision_deadlines();
select is((select count(*) from app.domain_events where project_id=(select id from ctx)),(select n from event_total),'Deleted project ignored; facts preserved');
select ok(exists(select 1 from app.automation_action_runs a join app.domain_events e on e.id=a.event_id where e.project_id=(select id from ctx)),'Historical action receipts retained');

select * from finish();
rollback;
